const items = $input.all();
const cutoff = Date.now() - 7 * 24 * 60 * 60 * 1000;

const DOM = [
  ['datacenterdynamics', 'Data Center Dynamics'],
  ['datacenterknowledge', 'Data Center Knowledge'],
  ['tomshardware', "Tom's Hardware"],
  ['siliconangle', 'SiliconANGLE'],
  ['marktechpost', 'MarkTechPost'],
  ['techcrunch.com/category/startups', 'TechCrunch VC'],
  ['techcrunch.com', 'TechCrunch AI'],
  ['theverge', 'The Verge'],
  ['arstechnica', 'Ars Technica']
];

const p1_keywords = ['frontier', 'foundation model', 'reasoning model', 'llm', 'deepseek', 'gpt-5', 'o3', 'claude 3.5', 'gemini 2', 'meta llama', 'weights', 'inference model', 'reinforcement learning', 'transformer', 'rag', 'agent'];
const p2_keywords = ['nvidia', 'blackwell', 'rubin', 'b200', 'gpu', 'tpu', 'semiconductor', 'foundry', 'tsmc', 'asml', 'amd', 'mi300', 'intel 18a', 'airjet', 'cooling', 'wafer', 'transistor', 'packaging', 'co-packaged'];
const p3_keywords = ['data center', 'datacenter', 'nuclear', 'power grid', 'gigawatt', 'megawatt', 'smr', 'substation', 'utility', 'energy', 'ppa', 'geothermal', 'transmission', 'hyperscale', 'blackstone'];
const p4_keywords = ['equity', 'million', 'raises', 'valuation', 'funding', 'billion', 'acquisition', 'venture', 'series a', 'series b', 'series c', 'debt', 'private equity', 'capital raise', 'buyout', 'ipo', 'acqui-hire', 'stake'];
const p5_keywords = ['enterprise', 'shadow ai', 'governance', 'regulation', 'ftc', 'antitrust', 'compliance', 'security', 'enterprise adoption', 'cio', 'ciso', 'workforce'];

const seen = new Set();
const cleanStr = s => (s || '').toString().toLowerCase();

const scored = items.map(it => {
  const j = it.json;
  const title = (j.title || '').toString();
  const desc = (j.contentSnippet || j.content || j.description || '').toString();
  const ds = j.isoDate || j.pubDate;
  const dt = ds ? new Date(ds).getTime() : 0;
  const text = cleanStr(title + ' ' + desc);
  const blob = cleanStr(JSON.stringify(j));

  let source = 'AI Intelligence Desk';
  for (const [dom, name] of DOM) {
    if (blob.includes(dom)) { source = name; break; }
  }

  const s1 = p1_keywords.reduce((a, k) => a + (text.includes(k) ? 2 : 0), 0);
  const s2 = p2_keywords.reduce((a, k) => a + (text.includes(k) ? 2 : 0), 0);
  const s3 = p3_keywords.reduce((a, k) => a + (text.includes(k) ? 2 : 0), 0);
  const s4 = p4_keywords.reduce((a, k) => a + (text.includes(k) ? 2 : 0), 0);
  const s5 = p5_keywords.reduce((a, k) => a + (text.includes(k) ? 2 : 0), 0);

  let pillar = 'ENTERPRISE AI & GOVERNANCE';
  let maxScore = s5;
  if (s1 >= maxScore && s1 > 0) { pillar = 'FRONTIER MODELS & RESEARCH'; maxScore = s1; }
  if (s2 > maxScore) { pillar = 'AI SILICON & SEMICONDUCTORS'; maxScore = s2; }
  if (s3 > maxScore) { pillar = 'DATA CENTERS & POWER'; maxScore = s3; }
  if (s4 > maxScore) { pillar = 'AI INVESTMENT & M&A'; maxScore = s4; }

  return { title, desc, dt, s1, s2, s3, s4, s5, source, pillar, maxScore };
})
.filter(x => x.title && (x.dt >= cutoff || x.dt === 0) && x.maxScore > 0)
.filter(x => {
  const k = x.title.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 40);
  if (seen.has(k)) return false;
  seen.add(k);
  return true;
});

const p1List = scored.filter(x => x.pillar === 'FRONTIER MODELS & RESEARCH').sort((a,b) => b.s1 - a.s1 || b.dt - a.dt);
const p2List = scored.filter(x => x.pillar === 'AI SILICON & SEMICONDUCTORS').sort((a,b) => b.s2 - a.s2 || b.dt - a.dt);
const p3List = scored.filter(x => x.pillar === 'DATA CENTERS & POWER').sort((a,b) => b.s3 - a.s3 || b.dt - a.dt);
const p4List = scored.filter(x => x.pillar === 'AI INVESTMENT & M&A').sort((a,b) => b.s4 - a.s4 || b.dt - a.dt);
const p5List = scored.filter(x => x.pillar === 'ENTERPRISE AI & GOVERNANCE').sort((a,b) => b.s5 - a.s5 || b.dt - a.dt);

const selected = [];
if (p1List[0]) selected.push(p1List[0]);
if (p2List[0]) selected.push(p2List[0]);
if (p3List[0]) selected.push(p3List[0]);
if (p4List[0]) selected.push(p4List[0]);
if (p1List[1]) selected.push(p1List[1]);
if (p2List[1]) selected.push(p2List[1]);
if (p3List[1]) selected.push(p3List[1]);
if (p4List[1]) selected.push(p4List[1]);
if (p5List[0]) selected.push(p5List[0]);

const remaining = scored.filter(x => !selected.includes(x)).sort((a,b) => b.maxScore - a.maxScore || b.dt - a.dt);
while (selected.length < 9 && remaining.length) {
  selected.push(remaining.shift());
}

return selected.slice(0, 9).map((x, i) => ({
  json: {
    index: i + 1,
    title: x.title,
    content: x.desc.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 600),
    source: x.source,
    pillar: x.pillar
  }
}));

const outs = $input.all();
const filt = $('Filter - Weekly AI & Infrastructure').all();
const parse = c => { try { const m = String(c).match(/\{[\s\S]*\}/); return m ? JSON.parse(m[0]) : null; } catch(e){ return null; } };
const clean = t => String(t).replace(/[<>]/g,'').trim();

const stories = [];
const scripts = [];

for (let i = 0; i < outs.length; i++) {
  const content = (outs[i].json.message && outs[i].json.message.content) || outs[i].json.content || outs[i].json.text || '';
  const p = parse(content) || {};
  const f = filt[i] ? filt[i].json : {};
  const script = clean(p.script || content);
  if (!script) continue;
  scripts.push(script);

  stories.push({
    index: i + 1,
    headline: clean(p.headline || f.title || 'AI Development').slice(0, 75),
    source: clean(f.source || 'AI Intelligence Desk'),
    category: clean(p.category || f.pillar || 'AI INTELLIGENCE').slice(0, 35),
    metric1_lbl: clean(p.metric1_lbl || 'KEY BENCHMARK').slice(0, 26),
    metric1_val: clean(p.metric1_val || 'HIGH IMPACT').slice(0, 24),
    metric2_lbl: clean(p.metric2_lbl || 'DEPLOYMENT SCALE').slice(0, 26),
    metric2_val: clean(p.metric2_val || 'ENTERPRISE').slice(0, 24),
    analysis: clean(p.analysis || 'Strategic AI development transforming compute architecture and enterprise deployment.').slice(0, 145),
    implication: clean(p.implication || 'Accelerates enterprise adoption of next-generation AI infrastructure and autonomous workflows.').slice(0, 135),
    script,
    words: script.split(/\s+/).filter(Boolean).length
  });
}

if (!stories.length) throw new Error('No AI stories to build');

const now = new Date();
const date = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
const dateFormatted = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

const anchorIntro = "Good morning. From the tech desk, this is The A.I. Dispatch for Friday. Here is this week’s comprehensive executive briefing on frontier models, silicon architecture, hyperscale power, and venture capital.";
const introWords = anchorIntro.split(/\s+/).filter(Boolean).length;

const anchorOutro = "That concludes this week’s executive briefing. The A.I. Dispatch publishes every Friday morning. Subscribe to byte f y i for authoritative intelligence fit to compute.";
const outroWords = anchorOutro.split(/\s+/).filter(Boolean).length;

const voiceover = anchorIntro + "  " + scripts.join("  ") + "  " + anchorOutro;

let cumulativeSec = 14;
const chapters = ['0:00 - Executive Briefing Intro'];
stories.forEach((s, idx) => {
  const m = Math.floor(cumulativeSec / 60);
  const sec = Math.floor(cumulativeSec % 60);
  chapters.push(`${m}:${String(sec).padStart(2, '0')} - Story ${idx + 1}: [${s.category}] ${s.headline}`);
  cumulativeSec += (s.words * 0.44);
});
const outroMin = Math.floor(cumulativeSec / 60);
const outroSec = Math.floor(cumulativeSec % 60);
chapters.push(`${outroMin}:${String(outroSec).padStart(2, '0')} - Strategic Takeaway & Signoff`);

const ytTitle = clean(`The AI Dispatch: Frontier Models, Silicon & Gigawatt Data Centers (${date})`).slice(0, 95);
const ytDescription = clean(`The AI Dispatch - Friday Executive Intelligence Briefing (${dateFormatted}):\n\n` +
  chapters.join('\n') + '\n\n' +
  "THIS WEEK'S COVERAGE:\n" +
  stories.map((s,i) => `${i+1}. [${s.category}] ${s.headline} (${s.source})\n- What Happened: ${s.analysis}\n- Impact: ${s.implication}`).join('\n\n') +
  `\n\nPublished weekly by @bytefyi.\n\n#ArtificialIntelligence #DataCenters #AIChips #Nvidia #OpenAI #TechNews #Semiconductors #VentureCapital`).slice(0, 4200);

const ytTags = ['ai news', 'weekly ai news', 'data centers', 'ai silicon', 'nvidia', 'openai', 'the ai dispatch', 'frontier models', 'semiconductors'].join(',');
const igCaption = `⚡ The AI Dispatch (${date})\n\nWeekly executive briefing on frontier models, silicon, and hyperscale energy:\n\n` +
  stories.map((s, i) => `${i+1}. [${s.category}] ${s.headline}`).join('\n') +
  `\n\nFollow @bytefyi for weekly AI intelligence 🛡️\n\n#ArtificialIntelligence #DataCenters #AIChips #TechNews #OpenAI`;

return [{ json: { fullScriptForCreatomate: voiceover, anchorIntro, anchorOutro, stories, introWords, outroWords, dateFormatted, currentDateFormatted: date, ytTitle, ytDescription, ytTags, igCaption } }];

const item = $input.first();
const j = item.json;
const audioBase64 = j.audioContent || j.audio_base64;
if (!audioBase64) throw new Error('No audio base64 from ElevenLabs');

const align = j.alignment || j.normalized_alignment;
let exactDuration = 0;
if (align && Array.isArray(align.character_end_times_seconds) && align.character_end_times_seconds.length) {
  exactDuration = Math.ceil(align.character_end_times_seconds[align.character_end_times_seconds.length - 1] + 1);
}

const prep = $('Code - Prepare Voiceover & Metadata').first().json;
const stories = prep.stories || [];
const dur = exactDuration || Math.max(15, Math.ceil(stories.reduce((a, s) => a + (s.words || 1), 0) * 0.42 + 6));
const filename = `ai_editorial_narration_${Date.now()}.mp3`;

const buffer = Buffer.from(audioBase64, 'base64');

return [{
  json: {
    audioDuration: dur,
    ytTitle: prep.ytTitle,
    ytDescription: prep.ytDescription,
    ytTags: prep.ytTags,
    igCaption: prep.igCaption
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/mpeg',
      fileName: filename
    }
  }
}];

const d = $('Code - Prepare Voiceover & Metadata').first().json;
const stories = d.stories || [];
const date = d.currentDateFormatted || '';
const audioUrl = $json.mediaLink;
const dur = Math.max(30, ($('Move & Rename Binary Data').first().json.audioDuration) || 105);
const introWords = d.introWords || 28;
const outroWords = d.outroWords || 22;
const anchorIntro = d.anchorIntro || 'Good morning. From the tech desk, this is The AI Dispatch for Friday—covering frontier models, silicon architecture, hyperscale power, and venture capital.';
const anchorOutro = d.anchorOutro || 'That concludes this week’s executive briefing. The AI Dispatch publishes every Friday morning. Follow @bytefyi.';

const total = Math.max(30, Math.ceil(dur * 10) / 10);
const storyWords = stories.reduce((a, s) => a + (s.words || 22), 0) || 1;
const grand = introWords + storyWords + outroWords;

const RECT = 'M 0 0 L 100 0 L 100 100 L 0 100 Z';
const F = 'Montserrat';
const BG = '#060B14';
const WHITE = '#FFFFFF';
const SLATE = '#94A3B8';
const CYAN = '#38BDF8';
const AMBER = '#FBBF24';
const INDIGO = '#6366F1';
const EMERALD = '#10B981';

const getIllustration = (cat) => {
  const c = String(cat || '').toUpperCase();
  if (c.includes('DATA CENTER') || c.includes('POWER') || c.includes('ENERGY') || c.includes('GRID')) {
    return 'https://storage.googleapis.com/bytesized-truths-audio-shorts/nyt_datacenter_illustration.png';
  }
  if (c.includes('SILICON') || c.includes('CHIP') || c.includes('HARDWARE') || c.includes('GPU')) {
    return 'https://storage.googleapis.com/bytesized-truths-audio-shorts/nyt_silicon_illustration.png';
  }
  if (c.includes('VENTURE') || c.includes('CAPITAL') || c.includes('FUNDING') || c.includes('ACQUISITION') || c.includes('INVESTMENT')) {
    return 'https://storage.googleapis.com/bytesized-truths-audio-shorts/nyt_venture_illustration.png';
  }
  if (c.includes('ENTERPRISE') || c.includes('GOVERNANCE') || c.includes('POLICY') || c.includes('REGULATION')) {
    return 'https://storage.googleapis.com/bytesized-truths-audio-shorts/nyt_enterprise_illustration.png';
  }
  return 'https://storage.googleapis.com/bytesized-truths-audio-shorts/nyt_frontier_illustration.png';
};

const els = [];
const fade = [{ type: 'fade', duration: 0.25 }];
const box = o => els.push(Object.assign({ type: 'shape', path: RECT }, o));
const txt = o => els.push(Object.assign({
  type: 'text',
  font_family: F,
  fill_color: WHITE,
  x_anchor: '50%',
  y_anchor: '50%',
  x_alignment: '50%',
  y_alignment: '50%',
  text_alignment: 'center'
}, o));

// 1. Dark Executive Canvas + Top Safe-Zone Guard (0..210px clear for Instagram Reels UI)
box({ x: '50%', y: '50%', width: '100%', height: '100%', fill_color: BG, time: 0, duration: total });
box({ x: '50%', y: '105px', width: '100%', height: '210px', fill_color: '#04070E', time: 0, duration: total });

// 2. Crisp Modern Masthead Card ("THE AI DISPATCH" at y=280px, completely below Instagram Reels header)
box({ x: '50%', y: '280px', width: '90%', height: '110px', border_radius: '20px', fill_color: '#0B1528', border_color: '#253B5E', border_width: '2px', time: 0, duration: total });
box({ x: '16.5%', y: '280px', width: '17%', height: '74px', border_radius: '14px', fill_color: INDIGO, time: 0, duration: total });
txt({ text: 'AI\nWEEKLY', x: '16.5%', y: '280px', width: '16%', font_size: '22px', font_weight: '800', line_height: '105%', fill_color: WHITE, time: 0, duration: total });
txt({ text: 'THE AI DISPATCH', x: '52%', y: '262px', width: '48%', font_size: '32px', font_weight: '800', fill_color: WHITE, text_alignment: 'left', time: 0, duration: total });
txt({ text: `EXECUTIVE INTELLIGENCE • ${date}`, x: '52%', y: '302px', width: '48%', font_size: '18px', font_weight: '700', fill_color: CYAN, text_alignment: 'left', time: 0, duration: total });
box({ x: '85.5%', y: '280px', width: '14%', height: '64px', border_radius: '14px', fill_color: '#112240', border_color: CYAN, border_width: '1.5px', time: 0, duration: total });

// 3. Intro Scene
const nStories = Math.max(1, stories.length);
const intro_dur = (introWords / grand) * total;
txt({ text: 'INTRO', x: '85.5%', y: '280px', width: '13%', font_size: '22px', font_weight: '800', fill_color: CYAN, time: 0, duration: intro_dur });
box({ x: '50%', y: '865px', width: '90%', height: '970px', border_radius: '28px', fill_color: '#091324', border_color: '#1E3A5F', border_width: '2px', time: 0, duration: intro_dur, animations: fade });
box({ x: '50%', y: '383px', width: '90%', height: '6px', border_radius: '3px', fill_color: INDIGO, time: 0, duration: intro_dur });
box({ x: '50%', y: '560px', width: '82%', height: '270px', border_radius: '20px', fill_color: '#F8FAFC', border_color: '#38BDF888', border_width: '2px', time: 0, duration: intro_dur });
els.push({ type: 'image', source: 'https://storage.googleapis.com/bytesized-truths-audio-shorts/nyt_frontier_illustration.png', x: '50%', y: '560px', width: '78%', height: '250px', fit: 'contain', border_radius: '16px', time: 0, duration: intro_dur });
txt({ text: 'THIS WEEK IN ARTIFICIAL INTELLIGENCE', x: '50%', y: '785px', width: '82%', font_size: '42px', font_weight: '800', line_height: '115%', fill_color: WHITE, time: 0, duration: intro_dur });
box({ x: '50%', y: '985px', width: '82%', height: '165px', border_radius: '18px', fill_color: '#0D1B33', border_color: '#1E3A5F', border_width: '1.5px', time: 0, duration: intro_dur });
txt({ text: `${nStories} PIVOTAL AI BREAKTHROUGHS`, x: '50%', y: '955px', width: '78%', font_size: '36px', font_weight: '800', fill_color: CYAN, time: 0, duration: intro_dur });
txt({ text: 'FRONTIER MODELS • SILICON • GIGAWATT POWER • VENTURE', x: '50%', y: '1022px', width: '78%', font_size: '21px', font_weight: '700', fill_color: AMBER, time: 0, duration: intro_dur });
box({ x: '50%', y: '1210px', width: '82%', height: '190px', border_radius: '20px', fill_color: '#06281E', border_color: EMERALD, border_width: '2px', time: 0, duration: intro_dur });
txt({ text: 'FRIDAY EXECUTIVE DOSSIER', x: '50%', y: '1170px', width: '76%', font_size: '22px', font_weight: '800', fill_color: EMERALD, time: 0, duration: intro_dur });
txt({ text: 'Structured 60-second intelligence briefing for builders, operators, and investors.', x: '50%', y: '1235px', width: '76%', font_size: '27px', font_weight: '600', line_height: '122%', fill_color: '#ECFDF5', time: 0, duration: intro_dur });
box({ x: '50%', y: '1465px', width: '90%', height: '175px', border_radius: '22px', fill_color: '#0B1528', border_color: '#38BDF866', border_width: '1.5px', time: 0, duration: intro_dur });
txt({ text: 'LIVE VOICEOVER TRANSCRIPT', x: '50%', y: '1406px', width: '82%', font_size: '19px', font_weight: '800', fill_color: CYAN, text_alignment: 'left', time: 0, duration: intro_dur });
txt({ text: `"${anchorIntro}"`, x: '50%', y: '1482px', width: '82%', font_size: '24px', font_weight: '600', line_height: '122%', fill_color: '#E2E8F0', text_alignment: 'left', time: 0, duration: intro_dur });

// 4. Dynamic Story Scenes
let cum = introWords;
stories.forEach((s, idx) => {
  const s_words = s.words || 22;
  const s_start = (cum / grand) * total;
  const s_dur = (s_words / grand) * total;
  cum += s_words;

  const illUrl = getIllustration(s.category);
  const headline = String(s.headline || 'AI Breakthrough');
  const m1_lbl = String(s.metric1_lbl || 'KEY BENCHMARK').toUpperCase();
  const m1_val = String(s.metric1_val || 'ENTERPRISE').toUpperCase();
  const m2_lbl = String(s.metric2_lbl || 'DEPLOYMENT SCALE').toUpperCase();
  const m2_val = String(s.metric2_val || 'PRODUCTION').toUpperCase();

  // Masthead Counter + 9-Segment Progress Bar
  txt({ text: `${idx + 1} / ${nStories}`, x: '85.5%', y: '280px', width: '13%', font_size: '26px', font_weight: '800', fill_color: CYAN, time: s_start, duration: s_dur });
  for (let k = 0; k < nStories; k++) {
    const segW = (90 - (nStories - 1) * 1.0) / nStories;
    const segX = 5 + segW / 2 + k * (segW + 1.0);
    const segCol = k === idx ? INDIGO : (k < idx ? '#0284C7' : '#1E293B');
    box({ x: `${segX.toFixed(2)}%`, y: '356px', width: `${segW.toFixed(2)}%`, height: '8px', border_radius: '4px', fill_color: segCol, time: s_start, duration: s_dur });
  }

  // Main Story Card
  box({ x: '50%', y: '865px', width: '90%', height: '970px', border_radius: '28px', fill_color: '#091324', border_color: '#1E3A5F', border_width: '2px', time: s_start, duration: s_dur, animations: fade });
  box({ x: '50%', y: '383px', width: '90%', height: '6px', border_radius: '3px', fill_color: INDIGO, time: s_start, duration: s_dur });

  // Category Pill (Left) + Source Pill (Right)
  box({ x: '30%', y: '430px', width: '42%', height: '48px', border_radius: '12px', fill_color: '#1E1B4B', border_color: INDIGO, border_width: '1.5px', time: s_start, duration: s_dur });
  txt({ text: String(s.category || 'AI INTELLIGENCE').toUpperCase(), x: '30%', y: '430px', width: '40%', font_size: '20px', font_weight: '800', fill_color: '#C7D2FE', time: s_start, duration: s_dur });

  box({ x: '73%', y: '430px', width: '36%', height: '48px', border_radius: '12px', fill_color: '#0F1D36', border_color: '#F59E0B88', border_width: '1.5px', time: s_start, duration: s_dur });
  txt({ text: `SOURCE: ${String(s.source || 'AI DESK').toUpperCase()}`, x: '73%', y: '430px', width: '34%', font_size: '19px', font_weight: '700', fill_color: AMBER, time: s_start, duration: s_dur });

  // Split Hero Row: Framed Illustration (Left) + 2 Labeled Benchmark Cards (Right)
  box({ x: '24.5%', y: '582px', width: '31%', height: '212px', border_radius: '18px', fill_color: '#F8FAFC', border_color: '#38BDF888', border_width: '2px', time: s_start, duration: s_dur });
  els.push({ type: 'image', source: illUrl, x: '24.5%', y: '582px', width: '29%', height: '196px', fit: 'contain', border_radius: '14px', time: s_start, duration: s_dur });

  box({ x: '66.5%', y: '526px', width: '49%', height: '100px', border_radius: '16px', fill_color: '#0E1E38', border_color: '#1E3A5F', border_width: '1.5px', time: s_start, duration: s_dur });
  box({ x: '42.5%', y: '526px', width: '6px', height: '100px', border_radius: '3px', fill_color: CYAN, time: s_start, duration: s_dur });
  txt({ text: m1_lbl, x: '67.5%', y: '500px', width: '44%', font_size: '18px', font_weight: '800', fill_color: CYAN, text_alignment: 'left', time: s_start, duration: s_dur });
  txt({ text: m1_val, x: '67.5%', y: '544px', width: '44%', font_size: m1_val.length > 16 ? '24px' : '28px', font_weight: '800', fill_color: WHITE, text_alignment: 'left', time: s_start, duration: s_dur });

  box({ x: '66.5%', y: '638px', width: '49%', height: '100px', border_radius: '16px', fill_color: '#0E1E38', border_color: '#1E3A5F', border_width: '1.5px', time: s_start, duration: s_dur });
